    ('Pseudofed 60 mg', 'Pseudoephedrin hydroclorid', '60 mg', 'Viên nén', NULL, NULL, NULL),
    ('Thiazifar 25 mg', 'Hydroclorothiazid', '25 mg', 'Viên nén', NULL, NULL, NULL),
    ('Tracleer 62,5 mg', 'Bosentan', '62,5 mg', 'Viên nén bao phim', NULL, NULL, NULL),
    ('Xylocaine Jelly 2%', 'Lidocain hydroclorid', '2%', 'Gel', NULL, NULL, NULL),
