-- active_ingredient_interactions (version 1; trigger interaction_rule_set_rule_id điền rule_id)
INSERT INTO active_ingredient_interactions (version, ingredient_a_id, ingredient_b_id, ingredient_b_in_table_a, interaction_type, severity_level, handling_type, min_interval_hours, description, source, verification_status)
SELECT 1, a.id, b.id, 'co'::yes_no, v.interaction_type::interaction_type, v.severity_level, v.handling_type::handling_type, v.min_interval_hours::numeric, v.description, v.source, 'da_xac_minh'
FROM (VALUES
    ('Amlodipin', 'Clarithromycin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm tăng tác dụng độc của thuốc chẹn kênh calci (như amlodipin).', 'Dược thư Quốc gia Việt Nam 2018, tr. 406'),
    ('Aspirin', 'Ibuprofen', 'chong_chi_dinh', 3, 'tranh_phoi_hop', NULL, 'Dùng ibuprofen cùng aspirin làm tăng nguy cơ chảy máu dạ dày và làm giảm tác dụng chống kết tập tiểu cầu của aspirin, tăng nguy cơ tim mạch. Khuyến cáo không nên dùng đồng thời; nếu phải dùng với aspirin liều thấp giải phóng ngay, FDA khuyến cáo uống ibuprofen 8 giờ trước hoặc ít nhất 30 phút sau aspirin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 788'),
    ('Aspirin', 'Spironolacton', 'chong_chi_dinh', 1, 'can_theo_doi', NULL, 'Aspirin đối kháng tác dụng tăng thải natri niệu của spironolacton.', 'Dược thư Quốc gia Việt Nam 2018, tr. 118'),
    ('Atorvastatin', 'Clarithromycin', 'phu_thuoc_lieu', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm tăng tác dụng độc của các chất ức chế HMG-CoA reductase (statin); phối hợp statin với thuốc ức chế CYP3A4 làm gặp viêm cơ và tiêu cơ vân nhiều hơn.', 'Dược thư Quốc gia Việt Nam 2018, tr. 288, 406'),
    ('Atorvastatin', 'Fluconazol', 'phu_thuoc_lieu', 3, 'giam_lieu', NULL, 'Fluconazol (thuốc chống nấm azol) có thể ức chế chuyển hóa atorvastatin qua CYP3A4, làm tăng nồng độ trong huyết tương và tác dụng không mong muốn của statin; đã xảy ra tiêu cơ vân cấp và độc tính với gan. Nếu thật cần phối hợp, cần xem xét giảm liều statin và theo dõi cẩn thận đáp ứng của người bệnh.', 'Tương tác thuốc và chú ý khi chỉ định 2015, tr. 887–888, 1042'),
    ('Bisoprolol', 'Digoxin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Thuốc chẹn beta (như bisoprolol) có thể làm tăng tác dụng làm chậm nhịp tim của digoxin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 266'),
    ('Bisoprolol', 'Ibuprofen', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Thuốc chống viêm không steroid (như ibuprofen) có thể làm giảm tác dụng hạ huyết áp của bisoprolol.', 'Dược thư Quốc gia Việt Nam 2018, tr. 266'),
    ('Ciprofloxacin', 'Ibuprofen', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Dùng đồng thời thuốc chống viêm không steroid (như ibuprofen) làm tăng tác dụng phụ của ciprofloxacin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 398'),
    ('Clopidogrel', 'Cimetidin', 'chong_chi_dinh', 3, 'tranh_phoi_hop', NULL, 'Cimetidin ức chế CYP2C19, làm giảm chất chuyển hóa có hoạt tính và giảm tác dụng kháng tiểu cầu của clopidogrel. Nhà sản xuất khuyến cáo tránh phối hợp.', 'Dược thư Quốc gia Việt Nam 2018, tr. 427–428'),
    ('Clopidogrel', 'Clarithromycin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm giảm tác dụng của clopidogrel.', 'Dược thư Quốc gia Việt Nam 2018, tr. 406'),
    ('Clopidogrel', 'Fluconazol', 'chong_chi_dinh', 3, 'tranh_phoi_hop', NULL, 'Fluconazol ức chế CYP2C19, làm giảm chất chuyển hóa có hoạt tính và giảm tác dụng kháng tiểu cầu của clopidogrel. Nhà sản xuất khuyến cáo tránh phối hợp.', 'Dược thư Quốc gia Việt Nam 2018, tr. 427–428'),
    ('Digoxin', 'Clarithromycin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm tăng tác dụng độc của glycosid tim; Dược thư cũng ghi kháng sinh macrolid làm tăng nồng độ/tác dụng của digoxin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 406, 530'),
    ('Enalapril', 'Aspirin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Aspirin và các thuốc chống viêm không steroid có thể làm giảm tác dụng huyết động (chống suy tim) của thuốc ức chế ACE như enalapril. Người suy tim cần điều trị lâu dài nên tránh phối hợp; dữ liệu hiện có chưa đủ để khuyến cáo thay đổi dùng aspirin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 586'),
    ('Felodipin', 'Cimetidin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Cimetidin ức chế CYP3A4, có thể ức chế chuyển hóa felodipin, làm tăng nồng độ và tác dụng của thuốc.', 'Dược thư Quốc gia Việt Nam 2018, tr. 651'),
    ('Felodipin', 'Clarithromycin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm tăng tác dụng độc của thuốc chẹn kênh calci (như felodipin).', 'Dược thư Quốc gia Việt Nam 2018, tr. 406'),
    ('Furosemid', 'Aspirin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Thuốc chống viêm không steroid (aspirin thuộc nhóm này) làm tăng nguy cơ độc với thận và giảm tác dụng lợi tiểu của furosemid.', 'Dược thư Quốc gia Việt Nam 2018, tr. 117, 704'),
    ('Furosemid', 'Digoxin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Furosemid làm hạ kali huyết, do đó làm tăng độc tính của digoxin (glycosid trợ tim) trên tim. Cần theo dõi khi dùng cùng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 704'),
    ('Furosemid', 'Ibuprofen', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Ibuprofen (thuốc chống viêm không steroid) làm tăng nguy cơ độc với thận và giảm tác dụng lợi tiểu của furosemid.', 'Dược thư Quốc gia Việt Nam 2018, tr. 704, 788'),
    ('Glibenclamid', 'Bosentan', 'chong_chi_dinh', 4, 'tranh_phoi_hop', NULL, 'Dùng đồng thời làm tăng nồng độ enzym aminotransferase trong huyết thanh (tăng nguy cơ tổn thương gan/độc tính tế bào gan) và giảm nồng độ cả hai thuốc trong huyết tương, làm giảm đáng kể hiệu quả kiểm soát glucose máu của Glibenclamid. Tránh phối hợp (chống chỉ định theo FDA và Martindale; DTQGVN khuyến cáo nên tránh dùng).', 'Dược thư Quốc gia Việt Nam 2018, tr. 729; Martindale The Complete Drug Reference 38th, tr. 1328'),
    ('Glibenclamid', 'Cimetidin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Cimetidin làm tăng tác dụng hạ glucose huyết của glibenclamid. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 729'),
    ('Glibenclamid', 'Ciprofloxacin', 'phu_thuoc_lieu', 3, 'can_theo_doi', NULL, 'Kháng sinh nhóm fluoroquinolon (ciprofloxacin) làm tăng tác dụng hạ glucose huyết của glibenclamid thông qua ức chế CYP2C9 và/hoặc kích thích bài tiết insulin, có thể dẫn đến hạ glucose máu trầm trọng và kéo dài (hạ đường huyết kháng trị). Cần giám sát chặt chẽ nồng độ glucose máu khi dùng đồng thời.', 'Dược thư Quốc gia Việt Nam 2018, tr. 396, 729; Martindale The Complete Drug Reference 38th, tr. 503'),
    ('Glibenclamid', 'Fluconazol', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Fluconazol làm tăng tác dụng hạ glucose huyết của glibenclamid. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 729'),
    ('Glibenclamid', 'Hydroclorothiazid', 'phu_thuoc_lieu', 2, 'can_theo_doi', NULL, 'Thuốc lợi tiểu thiazid (như hydroclorothiazid) làm giảm tác dụng hạ glucose huyết của glibenclamid. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 729'),
    ('Glibenclamid', 'Miconazol', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Miconazol làm tăng tác dụng hạ glucose huyết của glibenclamid. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 729'),
    ('Gliclazid', 'Captopril', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Thuốc ức chế enzym chuyển (như captopril) có thể làm tăng tác dụng hạ glucose huyết của gliclazid; cần thận trọng khi phối hợp.', 'Dược thư Quốc gia Việt Nam 2018, tr. 730'),
    ('Gliclazid', 'Enalapril', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Thuốc ức chế enzym chuyển (như enalapril) có thể làm tăng tác dụng hạ glucose huyết của gliclazid; cần thận trọng khi phối hợp.', 'Dược thư Quốc gia Việt Nam 2018, tr. 730'),
    ('Gliclazid', 'Fluconazol', 'phu_thuoc_lieu', 3, 'giam_lieu', NULL, 'Fluconazol ức chế chọn lọc enzym CYP2C9, làm tăng nồng độ trong huyết tương và kéo dài thời gian bán thải của gliclazid, làm tăng nguy cơ hạ đường huyết quá mức. Cần tăng cường tự theo dõi đường huyết chặt chẽ và cân nhắc giảm liều gliclazid trong và sau quá trình điều trị kháng nấm.', 'Dược thư Quốc gia Việt Nam 2018, tr. 668, 730; Tương tác thuốc và chú ý khi chỉ định 2015, tr. 788–789'),
    ('Gliclazid', 'Miconazol', 'chong_chi_dinh', 4, 'tranh_phoi_hop', NULL, 'Miconazol (đường toàn thân và gel bôi miệng) ức chế mạnh chuyển hóa của gliclazid qua CYP2C9, làm tăng tác dụng hạ glucose huyết quá mức, có thể dẫn đến xuất hiện các biểu hiện hạ glucose huyết nặng, thậm chí hôn mê. Chống chỉ định phối hợp tuyệt đối.', 'Dược thư Quốc gia Việt Nam 2018, tr. 730, 984; Tương tác thuốc và chú ý khi chỉ định 2015, tr. 788'),
    ('Gliclazid', 'Prednisolon', 'phu_thuoc_lieu', 3, 'can_theo_doi', NULL, 'Glucocorticoid (prednisolon đường toàn thân và tại chỗ) làm tăng glucose huyết do kích thích tân tạo glucose ở gan và làm giảm dung nạp glucose ở ngoại biên, đối kháng trực tiếp tác dụng điều trị của sulfonylurê. Cần thông báo cho người bệnh, tăng cường kiểm tra đường huyết và hiệu chỉnh tăng liều gliclazid trong và sau đợt dùng corticoid.', 'Dược thư Quốc gia Việt Nam 2018, tr. 730, 1175; Tương tác thuốc và chú ý khi chỉ định 2015, tr. 789'),
    ('Glimepirid', 'Clarithromycin', 'phu_thuoc_lieu', 3, 'can_theo_doi', NULL, 'Clarithromycin (kháng sinh macrolid) có thể làm tăng nguy cơ hạ glucose huyết khi dùng cùng các sulfonylurê; Martindale ghi nhận các ca hạ glucose huyết nặng khi phối hợp clarithromycin với sulfonylurê. Đây là tương tác ghi cho cả nhóm sulfonylurê, nguồn không nêu riêng glimepirid. Cần theo dõi đường huyết khi bắt đầu hoặc ngừng kháng sinh.', 'Martindale The Complete Drug Reference 38th, tr. 503'),
    ('Glimepirid', 'Fluconazol', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Fluconazol ức chế CYP2C9, làm thay đổi chuyển hóa và có thể làm tăng tác dụng hạ glucose huyết của glimepirid. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 732'),
    ('Glimepirid', 'Miconazol', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Miconazol có thể làm tăng tác dụng hạ glucose huyết của glimepirid, dẫn tới hạ đường huyết. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 732'),
    ('Ibuprofen', 'Digoxin', 'chong_chi_dinh', 1, 'can_theo_doi', NULL, 'Ibuprofen có thể làm tăng nồng độ digoxin trong huyết tương.', 'Dược thư Quốc gia Việt Nam 2018, tr. 788'),
    ('Insulin', 'Aspirin', 'phu_thuoc_lieu', 3, 'giam_lieu', NULL, 'Aspirin (salicylat) có thể làm hạ glucose huyết và tăng tác dụng của insulin. Ở liều cao (3,5–7,5 g/ngày) aspirin có thể làm giảm, thậm chí thay thế liều insulin cần dùng; ở liều 1,2–2,4 g/ngày không thấy thay đổi đáng kể nhu cầu insulin. Cần theo dõi đường huyết khi bắt đầu hoặc ngừng aspirin liều cao.', 'Martindale The Complete Drug Reference 38th, tr. 486; Tương tác thuốc và chú ý khi chỉ định 2015, tr. 758; Dược thư Quốc gia Việt Nam 2018, tr. 815'),
    ('Insulin', 'Enalapril', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Enalapril có thể gây hạ glucose huyết ở người đái tháo đường đang được kiểm soát bằng insulin. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 586'),
    ('Insulin', 'Hydroclorothiazid', 'phu_thuoc_lieu', 3, 'can_theo_doi', NULL, 'Hydroclorothiazid làm tăng glucose huyết; cần phải điều chỉnh liều thuốc chống đái tháo đường (insulin) khi dùng cùng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 778'),
    ('Insulin', 'Perindopril', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Cũng như các thuốc ức chế enzym chuyển khác, perindopril làm tăng tác dụng hạ glucose huyết của insulin. Cần theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1133'),
    ('Insulin', 'Propranolol', 'phu_thuoc_lieu', 3, 'can_theo_doi', NULL, 'Thuốc chẹn beta-adrenergic không chọn lọc (propranolol) có thể ức chế các triệu chứng thần kinh giao cảm báo hiệu hạ đường huyết (nhịp tim nhanh, đánh trống ngực, hồi hộp, run rẩy; tuy nhiên dấu hiệu vã mồ hôi thường không bị ức chế) và ức chế phân giải glycogen ở gan làm chậm quá trình phục hồi đường huyết. Khuyên người bệnh tăng cường tự theo dõi đường huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 814, 1205; Tương tác thuốc và chú ý khi chỉ định 2015, tr. 434, 794–795'),
    ('Loratadin', 'Cimetidin', 'chong_chi_dinh', 1, 'can_theo_doi', NULL, 'Cimetidin ức chế chuyển hóa loratadin, làm tăng nồng độ loratadin trong huyết tương khoảng 60%.', 'Dược thư Quốc gia Việt Nam 2018, tr. 924'),
    ('Metformin', 'Cimetidin', 'phu_thuoc_lieu', 2, 'can_theo_doi', NULL, 'Cimetidin làm giảm độ thanh lọc của metformin ở thận do cạnh tranh bài tiết qua hệ thống vận chuyển cation hữu cơ (OCT2) ở ống thận, làm tăng nồng độ đỉnh và sinh khả dụng của metformin trong huyết tương, tăng nguy cơ nhiễm toan acid lactic. Cần theo dõi đáp ứng lâm sàng và hiệu chỉnh giảm liều metformin nếu cần.', 'Dược thư Quốc gia Việt Nam 2018, tr. 391, 957; Tương tác thuốc và chú ý khi chỉ định 2015, tr. 135'),
    ('Metformin', 'Furosemid', 'phu_thuoc_lieu', 2, 'can_theo_doi', NULL, 'Furosemid làm tăng nồng độ đỉnh của metformin trong huyết tương do giảm thể tích dịch tuần hoàn và có thể làm suy giảm chức năng thận tạm thời, làm tăng nguy cơ tích lũy metformin và nhiễm toan lactic, đặc biệt ở bệnh nhân cao tuổi hoặc người có suy giảm chức năng thận từ trước. Tránh phối hợp nếu suy thận rõ rệt.', 'Tương tác thuốc và chú ý khi chỉ định 2015, tr. 137'),
    ('Nifedipin', 'Aspirin', 'chong_chi_dinh', 1, 'can_theo_doi', NULL, 'Tác dụng chống kết tập tiểu cầu tăng lên khi phối hợp nifedipin với aspirin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1058'),
    ('Nifedipin', 'Cimetidin', 'chong_chi_dinh', 3, 'giam_lieu', NULL, 'Cimetidin ức chế chuyển hóa nifedipin, làm tăng nồng độ và tác dụng của nifedipin; cần giảm liều khi phối hợp.', 'Dược thư Quốc gia Việt Nam 2018, tr. 391, 1058'),
    ('Nifedipin', 'Clarithromycin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm tăng tác dụng độc của thuốc chẹn kênh calci (như nifedipin).', 'Dược thư Quốc gia Việt Nam 2018, tr. 406'),
    ('Nifedipin', 'Digoxin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Nifedipin làm tăng nồng độ digoxin trong huyết thanh khoảng 15–45%; phải theo dõi dấu hiệu ngộ độc digoxin và giảm liều nếu cần.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1058'),
    ('Prednisolon', 'Fluconazol', 'chong_chi_dinh', 1, 'can_theo_doi', NULL, 'Fluconazol có thể làm tăng nồng độ/tác dụng của prednisolon.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1176'),
    ('Propranolol', 'Cimetidin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Cimetidin ức chế chuyển hóa ở gan, làm tăng nồng độ propranolol trong huyết tương; Dược thư xếp đây là tương tác có ý nghĩa lâm sàng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 391'),
    ('Propranolol', 'Pseudoephedrin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Thuốc chẹn beta như propranolol có thể làm tăng tác dụng tăng huyết áp của pseudoephedrin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1213'),
    ('Simvastatin', 'Amlodipin', 'phu_thuoc_lieu', 3, 'giam_lieu', NULL, 'Amlodipin ức chế CYP3A4, có thể làm tăng nồng độ simvastatin trong huyết tương và nguy cơ bệnh cơ. Liều simvastatin tối đa 20 mg/ngày khi dùng cùng amlodipin (theo thông tin sản phẩm được cấp phép tại Anh).', 'Martindale The Complete Drug Reference 38th, tr. 1489'),
    ('Simvastatin', 'Clarithromycin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clarithromycin có thể làm tăng tác dụng độc của các chất ức chế HMG-CoA reductase (statin); phối hợp statin với thuốc ức chế CYP3A4 làm gặp viêm cơ và tiêu cơ vân nhiều hơn.', 'Dược thư Quốc gia Việt Nam 2018, tr. 288, 406'),
    ('Simvastatin', 'Fluconazol', 'phu_thuoc_lieu', 3, 'giam_lieu', NULL, 'Fluconazol (thuốc chống nấm azol) có thể ức chế chuyển hóa simvastatin qua CYP3A4, làm tăng nồng độ trong huyết tương và tác dụng không mong muốn của statin; đã xảy ra tiêu cơ vân cấp và độc tính với gan. Nếu thật cần phối hợp, cần xem xét giảm liều statin và theo dõi cẩn thận đáp ứng của người bệnh.', 'Tương tác thuốc và chú ý khi chỉ định 2015, tr. 887–888, 1042'),
    ('Spironolacton', 'Captopril', 'chong_chi_dinh', 3, 'can_theo_doi', NULL, 'Dùng spironolacton cùng thuốc ức chế enzym chuyển (như captopril) có thể gây tăng kali huyết nặng, đe dọa tính mạng, nhất là ở người suy thận.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1303'),
    ('Spironolacton', 'Digoxin', 'chong_chi_dinh', 3, 'giam_lieu', NULL, 'Spironolacton làm tăng nửa đời của digoxin, dẫn đến tăng nồng độ và độc tính của digoxin. Nếu phải dùng đồng thời, cần theo dõi cẩn thận và điều chỉnh liều digoxin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 530, 1303'),
    ('Spironolacton', 'Enalapril', 'chong_chi_dinh', 3, 'can_theo_doi', NULL, 'Dùng spironolacton cùng thuốc ức chế enzym chuyển có thể gây tăng kali huyết nặng, đe dọa tính mạng, nhất là ở người suy thận. Nên theo dõi chặt chẽ và thường xuyên kiểm tra kali huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 585, 1303'),
    ('Spironolacton', 'Losartan', 'chong_chi_dinh', 3, 'can_theo_doi', NULL, 'Dùng spironolacton cùng thuốc đối kháng thụ thể angiotensin II (như losartan) có thể gây tăng kali huyết nặng, đe dọa tính mạng, nhất là ở người suy thận.', 'Dược thư Quốc gia Việt Nam 2018, tr. 928, 1303'),
    ('Spironolacton', 'Perindopril', 'chong_chi_dinh', 3, 'tranh_phoi_hop', NULL, 'Dùng spironolacton cùng thuốc ức chế enzym chuyển có thể gây tăng kali huyết nặng, đe dọa tính mạng, nhất là ở người suy thận. Không nên phối hợp, trừ trường hợp hạ kali huyết; nếu cần phối hợp phải thận trọng và thường xuyên kiểm tra kali huyết.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1133, 1303'),
    ('Spironolacton', 'Valsartan', 'chong_chi_dinh', 3, 'tranh_phoi_hop', NULL, 'Dùng spironolacton cùng valsartan có thể gây tăng kali huyết nặng; Dược thư không khuyến cáo dùng đồng thời valsartan với thuốc lợi tiểu giữ kali do nguy cơ tăng kali và creatinin huyết thanh ở người suy tim.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1303, 1455'),
    ('Warfarin', 'Aspirin', 'phu_thuoc_lieu', 4, 'tranh_phoi_hop', NULL, 'Aspirin (nhất là liều cao, đường toàn thân) làm tăng tác dụng chống đông của warfarin và tăng nguy cơ chảy máu do ức chế kết tập tiểu cầu và đẩy warfarin khỏi liên kết protein huyết tương. Dược thư ghi chống chỉ định phối hợp với aspirin liều cao.', 'Dược thư Quốc gia Việt Nam 2018, tr. 118, 1486'),
    ('Warfarin', 'Atorvastatin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Statin (trong đó có atorvastatin) có thể làm tăng tác dụng của warfarin. Cần theo dõi khi bắt đầu hoặc thay đổi liều statin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 288'),
    ('Warfarin', 'Cimetidin', 'chong_chi_dinh', 3, 'giam_lieu', NULL, 'Cimetidin ức chế chuyển hóa warfarin ở gan, làm tăng tác dụng chống đông. Dược thư xếp đây là tương tác có ý nghĩa lâm sàng với thuốc có chỉ số điều trị hẹp, có thể cần điều chỉnh liều.', 'Dược thư Quốc gia Việt Nam 2018, tr. 391, 1487'),
    ('Warfarin', 'Ciprofloxacin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Ciprofloxacin làm tăng tác dụng của thuốc chống đông uống như warfarin. Cần theo dõi khi dùng cùng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 398'),
    ('Warfarin', 'Clopidogrel', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Clopidogrel ức chế CYP2C19 làm tăng nồng độ warfarin và có thể làm tăng tác dụng/độc tính của warfarin. Cần theo dõi khi dùng cùng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 427–428'),
    ('Warfarin', 'Fluconazol', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Fluconazol làm tăng thời gian prothrombin khi dùng cùng warfarin; cần theo dõi cẩn thận thời gian prothrombin khi dùng đồng thời.', 'Dược thư Quốc gia Việt Nam 2018, tr. 668'),
    ('Warfarin', 'Ibuprofen', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Ibuprofen hiệp đồng tác dụng với warfarin, làm tăng nguy cơ chảy máu dạ dày. Cần theo dõi dấu hiệu chảy máu khi dùng cùng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 788'),
    ('Warfarin', 'Miconazol', 'chong_chi_dinh', 4, 'tranh_phoi_hop', NULL, 'Miconazol (đường toàn thân và gel bôi miệng) làm tăng dạng warfarin tự do trong máu và ức chế chuyển hóa warfarin, có thể gây chảy máu, đôi khi nặng. Dược thư ghi chống chỉ định phối hợp.', 'Dược thư Quốc gia Việt Nam 2018, tr. 986, 1486–1487'),
    ('Warfarin', 'Ofloxacin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Ofloxacin làm tăng tác dụng của warfarin, có nguy cơ gây chảy máu. Phải kiểm tra INR thường xuyên; có khi cần điều chỉnh liều thuốc chống đông trong và sau đợt dùng ofloxacin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1077'),
    ('Warfarin', 'Paracetamol', 'phu_thuoc_lieu', 2, 'can_theo_doi', NULL, 'Paracetamol (acetaminophen) có thể làm tăng tác dụng của warfarin. Cần theo dõi khi dùng cùng, nhất là khi dùng paracetamol thường xuyên.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1487'),
    ('Warfarin', 'Prednisolon', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Prednisolon có thể làm tăng nồng độ/tác dụng của warfarin; Dược thư cũng ghi corticoid có thể làm tăng hoặc giảm tác dụng của warfarin. Cần theo dõi khi dùng cùng.', 'Dược thư Quốc gia Việt Nam 2018, tr. 1176, 1487'),
    ('Warfarin', 'Simvastatin', 'chong_chi_dinh', 2, 'can_theo_doi', NULL, 'Statin (trong đó có simvastatin) có thể làm tăng tác dụng của warfarin. Cần theo dõi khi bắt đầu hoặc thay đổi liều statin.', 'Dược thư Quốc gia Việt Nam 2018, tr. 288')
) AS v (ingredient_a, ingredient_b, interaction_type, severity_level, handling_type, min_interval_hours, description, source)
JOIN active_ingredients a ON a.standard_name = v.ingredient_a
JOIN active_ingredients b ON b.standard_name = v.ingredient_b;

-- active_ingredient_interaction_dose_thresholds (gắn version hiện hành của quy tắc cha)
INSERT INTO active_ingredient_interaction_dose_thresholds (interaction_id, ingredient_ref, min_dose, max_dose, dose_unit, severity_level, warning_text)
SELECT i.id, v.ingredient_ref, v.min_dose::numeric, v.max_dose::numeric, v.dose_unit, v.severity_level, v.warning_text
FROM (VALUES
    ('Atorvastatin', 'Clarithromycin', 'A', NULL, 20, 'mg', 2, 'Atorvastatin đến 20 mg/ngày khi dùng cùng clarithromycin: trong giới hạn liều khuyến cáo (khởi đầu 10 mg, tối đa 20 mg/ngày); theo dõi đau cơ, yếu cơ.'),
    ('Atorvastatin', 'Clarithromycin', 'A', 21, NULL, 'mg', 3, 'Atorvastatin trên 20 mg/ngày khi dùng cùng clarithromycin: vượt liều tối đa khuyến cáo (20 mg/ngày), tăng nguy cơ bệnh cơ; cần giảm liều atorvastatin.'),
    ('Atorvastatin', 'Fluconazol', 'B', NULL, 200, 'mg', 2, 'Fluconazol đến 200 mg/ngày: vẫn có thể làm tăng nồng độ và tác dụng không mong muốn của atorvastatin; cần theo dõi đau cơ, yếu cơ.'),
    ('Atorvastatin', 'Fluconazol', 'B', 201, NULL, 'mg', 3, 'Fluconazol trên 200 mg/ngày ức chế CYP3A4, làm tăng nồng độ atorvastatin, nguy cơ tiêu cơ vân: nếu thật cần phối hợp phải giảm liều statin và theo dõi cẩn thận.'),
    ('Glibenclamid', 'Hydroclorothiazid', 'B', NULL, 12.5, 'mg', 1, 'Hydroclorothiazid liều thấp (đến 12,5 mg/ngày) có thể không ảnh hưởng đáng kể tới kiểm soát đường huyết khi dùng cùng glibenclamid.'),
    ('Insulin', 'Aspirin', 'B', NULL, 2400, 'mg', 1, 'Aspirin đến 2,4 g/ngày: có thể hạ nhẹ đường huyết nhưng không thay đổi đáng kể nhu cầu insulin.'),
    ('Insulin', 'Aspirin', 'B', 3500, NULL, 'mg', 3, 'Aspirin liều cao (từ 3,5 g/ngày) có thể làm giảm, thậm chí thay thế liều insulin cần dùng, gây hạ đường huyết: theo dõi đường huyết và điều chỉnh liều insulin.'),
    ('Insulin', 'Hydroclorothiazid', 'B', NULL, 12.5, 'mg', 1, 'Hydroclorothiazid liều thấp (đến 12,5 mg/ngày) có thể không ảnh hưởng đáng kể tới kiểm soát đường huyết khi dùng cùng insulin.'),
    ('Simvastatin', 'Amlodipin', 'A', NULL, 20, 'mg', 2, 'Simvastatin đến 20 mg/ngày khi dùng cùng amlodipin: trong giới hạn liều khuyến cáo; theo dõi đau cơ, yếu cơ.'),
    ('Simvastatin', 'Amlodipin', 'A', 21, NULL, 'mg', 3, 'Simvastatin trên 20 mg/ngày khi dùng cùng amlodipin: vượt liều tối đa khuyến cáo (20 mg/ngày), tăng nguy cơ bệnh cơ; cần giảm liều simvastatin.'),
    ('Simvastatin', 'Fluconazol', 'B', NULL, 200, 'mg', 2, 'Fluconazol đến 200 mg/ngày: vẫn có thể làm tăng nồng độ và tác dụng không mong muốn của simvastatin; cần theo dõi đau cơ, yếu cơ.'),
    ('Simvastatin', 'Fluconazol', 'B', 201, NULL, 'mg', 3, 'Fluconazol trên 200 mg/ngày ức chế CYP3A4, làm tăng nồng độ simvastatin, nguy cơ tiêu cơ vân: nếu thật cần phối hợp phải giảm liều statin và theo dõi cẩn thận.'),
    ('Warfarin', 'Aspirin', 'B', NULL, 199, 'mg', 3, 'Aspirin liều thấp (dưới 200 mg/ngày) dùng cùng warfarin: không nên kê đơn cùng nhau vì tăng nguy cơ chảy máu; trên thực tế chỉ phối hợp ở liều thấp này và cần bác sĩ theo dõi.'),
    ('Warfarin', 'Aspirin', 'B', 200, NULL, 'mg', 4, 'Aspirin từ 200 mg/ngày trở lên dùng cùng warfarin: chống chỉ định phối hợp vì tăng mạnh nguy cơ chảy máu.'),
    ('Warfarin', 'Paracetamol', 'B', NULL, 278, 'mg', 1, 'Paracetamol liều thấp (dưới khoảng 1.950 mg mỗi tuần, tức dưới 6 viên 325 mg/tuần) không ảnh hưởng lâm sàng đến tác dụng chống đông của warfarin.'),
    ('Warfarin', 'Paracetamol', 'B', 326, NULL, 'mg', 3, 'Paracetamol trên khoảng 325 mg/ngày (trên 2.275 mg/tuần) làm tăng tác dụng chống đông của warfarin: hạn chế paracetamol, xét nghiệm đông máu 1–2 lần/tuần khi bắt đầu hoặc ngừng paracetamol, điều chỉnh liều thuốc chống đông khi cần.')
) AS v (ingredient_a, ingredient_b, ingredient_ref, min_dose, max_dose, dose_unit, severity_level, warning_text)
JOIN active_ingredients a ON a.standard_name = v.ingredient_a
JOIN active_ingredients b ON b.standard_name = v.ingredient_b
JOIN active_ingredient_interactions i ON i.ingredient_a_id = a.id AND i.ingredient_b_id = b.id
    AND i.superseded_at IS NULL AND i.deleted_at IS NULL;

-- drug_food_interactions (version 1)
INSERT INTO drug_food_interactions (version, active_ingredient_id, food_to_avoid, severity_level, reason, source, verification_status)
SELECT 1, a.id, v.food_to_avoid, v.severity_level, v.reason, v.source, 'da_xac_minh'
FROM (VALUES
    ('Acarbose', 'Đường trắng (saccharose) và thức ăn nhiều đường', 1, 'Khi đang dùng acarbose, thức ăn chứa đường trắng (saccharose) thường gây khó chịu ở bụng hoặc tiêu chảy do đường lên men ở ruột. Hạn chế đồ ăn, đồ uống nhiều đường trắng. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Acarbose, tr. 104'),
    ('Atorvastatin', 'Bưởi chùm (grapefruit) và nước ép', 1, 'Nước ép bưởi chùm làm tăng lượng atorvastatin hấp thu vào máu. Lưu ý khi uống nước ép bưởi chùm. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Các chất ức chế HMG-CoA reductase, tr. 288'),
    ('Atorvastatin', 'Rượu và đồ uống có cồn', 2, 'Người uống nhiều rượu cần thận trọng khi dùng atorvastatin vì nguy cơ ảnh hưởng chức năng gan. Hạn chế rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Các chất ức chế HMG-CoA reductase, tr. 287'),
    ('Cetirizin', 'Rượu và đồ uống có cồn', 3, 'Rượu làm tăng tác dụng ức chế thần kinh (buồn ngủ) khi dùng cetirizin. Tránh uống rượu khi dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Cetirizin, tr. 382'),
    ('Cimetidin', 'Rượu và đồ uống có cồn', 2, 'Thận trọng khi uống rượu trong thời gian dùng cimetidin, nhất là khi lái xe hoặc vận hành máy móc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Cimetidin, tr. 391'),
    ('Ciprofloxacin', 'Rượu và đồ uống có cồn', 2, 'Ciprofloxacin có thể gây hoa mắt, chóng mặt, nhất là khi uống rượu. Thận trọng khi uống rượu, lái xe hoặc vận hành máy móc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Ciprofloxacin, tr. 396'),
    ('Ciprofloxacin', 'Sữa và thực phẩm giàu canxi', 2, 'Sữa, sữa chua và đồ uống bổ sung canxi uống riêng lúc dùng thuốc làm giảm nhiều hấp thu ciprofloxacin. Uống thuốc 2 giờ trước hoặc sau khi dùng các sản phẩm này. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Ciprofloxacin, tr. 396'),
    ('Ciprofloxacin', 'Đồ uống chứa caffeine', 2, 'Ciprofloxacin làm tăng tác dụng của caffeine; hạn chế cà phê, trà, nước tăng lực nếu có hồi hộp, rối loạn tim hoặc kích thích thần kinh. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Ciprofloxacin, tr. 396'),
    ('Clopidogrel', 'Thảo dược làm tăng tác dụng chống kết tập tiểu cầu', 2, 'Một số thảo dược (tỏi, gừng, nghệ, nhân sâm, bạch quả, trà xanh, cam thảo, hạt nho…) làm tăng tác dụng chống kết tập tiểu cầu của clopidogrel. Thận trọng khi dùng các thảo dược này. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Clopidogrel, tr. 428'),
    ('Dextromethorphan', 'Rượu và đồ uống có cồn', 3, 'Dextromethorphan có thể gây buồn ngủ; rượu làm tăng tác dụng này. Tránh uống rượu khi dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Dextromethorphan, tr. 509'),
    ('Digoxin', 'Cám và thực phẩm nhiều chất xơ', 1, 'Thức ăn nhiều chất xơ (cám) hoặc giàu pectin có thể làm giảm hấp thu digoxin. Lưu ý khi ăn nhiều cám, chất xơ cùng lúc uống thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Digoxin, tr. 530'),
    ('Enalapril', 'Muối thay thế chứa kali', 2, 'Dùng muối chứa kali cùng enalapril có thể gây tăng kali máu, nhất là ở người suy thận. Thận trọng và theo dõi kali máu. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Enalapril, tr. 585'),
    ('Felodipin', 'Bưởi chùm (grapefruit) và nước ép', 4, 'Nước ép bưởi chùm ức chế chuyển hóa felodipin, làm tăng nồng độ và tác dụng của thuốc. Không uống thuốc với nước ép bưởi chùm. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Felodipin, tr. 651'),
    ('Felodipin', 'Nhân sâm', 3, 'Nhân sâm có thể làm nặng thêm tình trạng tăng huyết áp. Tránh dùng nhân sâm cùng felodipin. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Felodipin, tr. 652'),
    ('Felodipin', 'Rượu và đồ uống có cồn', 2, 'Rượu làm tăng hấp thu felodipin nên làm tăng tác dụng của thuốc. Thận trọng khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Felodipin, tr. 652'),
    ('Felodipin', 'Tỏi', 3, 'Tỏi có thể làm tăng tác dụng hạ huyết áp của felodipin. Tránh dùng kèm tỏi. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Felodipin, tr. 652'),
    ('Fexofenadin', 'Bưởi chùm (grapefruit) và nước ép', 1, 'Nước ép bưởi chùm có thể làm giảm lượng fexofenadin hấp thu (tới khoảng 36%). Lưu ý khi uống nước ép bưởi chùm cùng lúc dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Fexofenadin, tr. 658'),
    ('Fexofenadin', 'Nước ép cam', 1, 'Nước cam ép có thể làm giảm lượng fexofenadin hấp thu (tới khoảng 36%). Lưu ý khi uống nước cam cùng lúc dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Fexofenadin, tr. 658'),
    ('Fexofenadin', 'Nước ép táo', 1, 'Nước táo ép có thể làm giảm lượng fexofenadin hấp thu (tới khoảng 36%). Lưu ý khi uống nước táo cùng lúc dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Fexofenadin, tr. 658'),
    ('Fexofenadin', 'Rượu và đồ uống có cồn', 3, 'Rượu làm tăng nguy cơ buồn ngủ khi dùng fexofenadin. Tránh uống rượu khi dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Fexofenadin, tr. 658'),
    ('Glibenclamid', 'Rượu và đồ uống có cồn', 2, 'Rượu làm tăng tác dụng hạ đường huyết của glibenclamid, dễ gây hạ đường huyết. Thận trọng khi uống rượu, bia và theo dõi đường huyết. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Glibenclamid, tr. 729'),
    ('Gliclazid', 'Rượu và đồ uống có cồn', 3, 'Rượu và đồ uống có cồn làm tăng nguy cơ hạ đường huyết khi dùng gliclazid. Không nên uống rượu, bia trong thời gian dùng thuốc. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Gliclazid, tr. 730'),
    ('Glimepirid', 'Rượu và đồ uống có cồn', 2, 'Rượu có thể làm tăng hoặc giảm tác dụng hạ đường huyết của glimepirid một cách khó đoán trước. Thận trọng khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Glimepirid, tr. 733'),
    ('Hydroclorothiazid', 'Cam thảo', 2, 'Cam thảo gây giữ nước, giữ natri và tăng mất kali khi dùng cùng hydroclorothiazid. Thận trọng khi dùng cam thảo. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Hydroclorothiazid, tr. 779'),
    ('Hydroclorothiazid', 'Nhân sâm', 3, 'Nhân sâm có thể làm tình trạng tăng huyết áp xấu hơn. Tránh dùng nhân sâm cùng hydroclorothiazid. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Hydroclorothiazid, tr. 779'),
    ('Hydroclorothiazid', 'Rượu và đồ uống có cồn', 2, 'Rượu dùng cùng hydroclorothiazid làm tăng nguy cơ hạ huyết áp khi đứng dậy. Thận trọng khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Hydroclorothiazid, tr. 778'),
    ('Insulin', 'Rượu và đồ uống có cồn', 2, 'Rượu làm tăng tác dụng hạ đường huyết của insulin và là yếu tố thuận lợi gây hạ đường huyết. Thận trọng khi uống rượu, bia và theo dõi đường huyết. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Insulin, tr. 815'),
    ('Ketotifen', 'Rượu và đồ uống có cồn', 2, 'Ketotifen là thuốc kháng histamin gây buồn ngủ; rượu làm tăng tác dụng an thần. Thận trọng khi uống rượu. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Martindale The Complete Drug Reference 38th, tr. 614, 631'),
    ('Losartan', 'Muối thay thế chứa kali', 2, 'Dùng muối thay thế chứa kali cùng losartan có thể gây tăng kali máu. Thận trọng khi dùng muối thay thế chứa kali. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Losartan, tr. 928'),
    ('Metformin', 'Rượu và đồ uống có cồn', 3, 'Rượu làm tăng nguy cơ nhiễm acid lactic và có thể gây hạ đường huyết khi đang dùng metformin. Tránh hoặc hạn chế uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Metformin, tr. 957'),
    ('Nifedipin', 'Bưởi chùm (grapefruit) và nước ép', 3, 'Nước ép bưởi chùm ức chế chuyển hóa nifedipin, làm tăng lượng thuốc trong máu. Tránh dùng nước ép bưởi chùm khi đang dùng nifedipin. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Nifedipin, tr. 1057'),
    ('Nifedipin', 'Rượu và đồ uống có cồn', 1, 'Rượu làm tăng lượng nifedipin hấp thu và ức chế chuyển hóa thuốc. Lưu ý khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Nifedipin, tr. 1058'),
    ('Paracetamol', 'Rượu và đồ uống có cồn', 3, 'Uống nhiều rượu, kéo dài làm tăng nguy cơ gây độc cho gan của paracetamol. Tránh hoặc hạn chế uống rượu. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Paracetamol, tr. 1119'),
    ('Prednisolon', 'Cỏ ban (St John''s wort)', 1, 'Cỏ ban (St John''s wort) có thể làm giảm nồng độ prednisolon trong máu. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Prednisolon, tr. 1176'),
    ('Prednisolon', 'Rượu và đồ uống có cồn', 3, 'Rượu có thể làm tăng kích ứng niêm mạc dạ dày khi dùng prednisolon. Tránh uống rượu. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Prednisolon, tr. 1176'),
    ('Prednisolon', 'Đồ uống chứa caffeine', 2, 'Dược thư khuyến cáo hạn chế caffeine (cà phê, trà, nước tăng lực) khi dùng prednisolon. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Prednisolon, tr. 1176'),
    ('Propranolol', 'Rượu và đồ uống có cồn', 1, 'Rượu làm chậm hấp thu propranolol. Lưu ý khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Propranolol, tr. 1206'),
    ('Repaglinid', 'Rượu và đồ uống có cồn', 4, 'Uống rượu khi dùng repaglinid làm tăng nguy cơ hạ đường huyết. Không uống rượu trong thời gian dùng repaglinid. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Repaglinid, tr. 1236'),
    ('Repaglinid', 'Thảo dược làm hạ đường huyết', 3, 'Một số thảo dược (mướp đắng, tỏi, nhân sâm, cần tây, lô hội, ngưu bàng, hồ lô ba…) có thể làm tăng nguy cơ hạ đường huyết khi dùng cùng repaglinid. Tránh dùng các thảo dược này. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Repaglinid, tr. 1236'),
    ('Simvastatin', 'Bưởi chùm (grapefruit) và nước ép', 3, 'Nước ép bưởi chùm làm tăng nồng độ simvastatin trong máu, tăng nguy cơ tổn thương cơ. Tránh uống nhiều nước ép bưởi chùm (trên 250 ml). Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Các chất ức chế HMG-CoA reductase, tr. 288'),
    ('Simvastatin', 'Rượu và đồ uống có cồn', 2, 'Người uống nhiều rượu cần thận trọng khi dùng simvastatin vì nguy cơ ảnh hưởng chức năng gan. Hạn chế rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Các chất ức chế HMG-CoA reductase, tr. 287'),
    ('Sitagliptin', 'Rượu và đồ uống có cồn', 2, 'Rượu có thể làm tăng tác dụng hạ đường huyết của sitagliptin. Thận trọng khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Sitagliptin, tr. 1294'),
    ('Spironolacton', 'Cam thảo', 3, 'Cam thảo tự nhiên có hoạt tính giống mineralocorticoid, đối kháng tác dụng của spironolacton. Tránh dùng cam thảo. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Spironolacton, tr. 1303'),
    ('Spironolacton', 'Muối thay thế chứa kali', 3, 'Muối thay thế (muối ăn kiêng ít natri) chứa kali có thể gây tăng kali máu khi dùng spironolacton. Tránh dùng muối thay thế chứa kali. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Spironolacton, tr. 1302'),
    ('Spironolacton', 'Rượu và đồ uống có cồn', 2, 'Rượu dùng cùng spironolacton làm tăng nguy cơ hạ huyết áp khi đứng dậy. Thận trọng khi uống rượu, bia. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Spironolacton, tr. 1303'),
    ('Spironolacton', 'Thực phẩm giàu kali', 3, 'Spironolacton giữ kali trong cơ thể; ăn nhiều thực phẩm giàu kali (chuối, các loại hạt…) có thể gây tăng kali máu. Tránh dùng nhiều thực phẩm giàu kali. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Spironolacton, tr. 1302'),
    ('Warfarin', 'Hành, tỏi và bạch quả (ginkgo)', 2, 'Dược thư liệt kê củ hành, tỏi, bạch quả (ginkgo biloba) trong mục tương tác của warfarin; các chất này có thể ảnh hưởng tác dụng chống đông. Thận trọng khi dùng nhiều hoặc dùng dạng chế phẩm. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Warfarin, tr. 1487'),
    ('Warfarin', 'Rau giàu vitamin K', 2, 'Vitamin K trong thức ăn (cà chua, rau diếp, cải bắp, súp lơ…) ảnh hưởng tác dụng chống đông của warfarin. Ăn lượng thức ăn giàu vitamin K đều đặn, không tăng giảm đột ngột. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Warfarin, tr. 1485'),
    ('Warfarin', 'Rượu và đồ uống có cồn', 3, 'Rượu (nghiện rượu) có thể làm giảm tác dụng của warfarin; nghiện rượu là một chống chỉ định của warfarin. Tránh uống rượu. Hãy hỏi bác sĩ hoặc dược sĩ nếu không chắc.', 'Dược thư Quốc gia Việt Nam 2018, chuyên luận Warfarin, tr. 1487')
) AS v (ingredient, food_to_avoid, severity_level, reason, source)
JOIN active_ingredients a ON a.standard_name = v.ingredient;

COMMIT;
